{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "intro_section",
        "actions_section"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Quarterly Expense Report Reminder",
        "variant": "h1"
      },
      "children": []
    },
    "intro_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "intro_heading",
        "intro_text",
        "email_card"
      ]
    },
    "intro_heading": {
      "type": "Text",
      "props": {
        "text": "Your Self-Reminder Draft",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Here is a draft reminder for your quarterly expense report submission:",
        "variant": "body"
      },
      "children": []
    },
    "email_card": {
      "type": "Card",
      "props": {},
      "children": [
        "email_card_stack"
      ]
    },
    "email_card_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "subject_label",
        "subject_text",
        "from_label",
        "from_text",
        "to_label",
        "to_text",
        "divider_1",
        "body_paragraph_1",
        "body_paragraph_2",
        "signature_line_1",
        "signature_line_2"
      ]
    },
    "subject_label": {
      "type": "Text",
      "props": {
        "text": "Subject:",
        "variant": "label"
      },
      "children": []
    },
    "subject_text": {
      "type": "Text",
      "props": {
        "text": "Action Required: Quarterly Expense Report Due",
        "variant": "h3"
      },
      "children": []
    },
    "from_label": {
      "type": "Text",
      "props": {
        "text": "From:",
        "variant": "label"
      },
      "children": []
    },
    "from_text": {
      "type": "Text",
      "props": {
        "text": "[Your Name]",
        "variant": "body"
      },
      "children": []
    },
    "to_label": {
      "type": "Text",
      "props": {
        "text": "To:",
        "variant": "label"
      },
      "children": []
    },
    "to_text": {
      "type": "Text",
      "props": {
        "text": "[Your Name]",
        "variant": "body"
      },
      "children": []
    },
    "divider_1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "body_paragraph_1": {
      "type": "Text",
      "props": {
        "text": "This is a reminder to submit your quarterly expense report to Accounting by September 30, 2024, at 5:00 PM PST.",
        "variant": "body"
      },
      "children": []
    },
    "body_paragraph_2": {
      "type": "Text",
      "props": {
        "text": "Please ensure all necessary receipts and documentation are attached.",
        "variant": "body"
      },
      "children": []
    },
    "signature_line_1": {
      "type": "Text",
      "props": {
        "text": "Thanks,",
        "variant": "body"
      },
      "children": []
    },
    "signature_line_2": {
      "type": "Text",
      "props": {
        "text": "[Your Name]",
        "variant": "body"
      },
      "children": []
    },
    "actions_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "actions_heading",
        "add_to_calendar_button"
      ]
    },
    "actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "add_to_calendar_button": {
      "type": "Button",
      "props": {
        "label": "Add to Calendar"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://calendar.google.com/calendar/render?action=TEMPLATE&text=Submit%20Quarterly%20Expense%20Report&dates=20240930T170000/20240930T170000&details=Submit%20your%20quarterly%20expense%20report%20to%20Accounting.%20Ensure%20all%20receipts%20and%20documentation%20are%20attached."
          }
        }
      }
    }
  }
}
